# server.py
from flask import Flask, Response, request
import redis
import json
from datetime import datetime
import threading
import time

app = Flask(__name__)
redis_client = redis.Redis(host='localhost', port=6379, db=0)

# In-memory store for demo; in production, use Redis or database
build_status = {}

def publish_event(channel, event_type, data):
    event = {
        "event_type": event_type,
        "data": data
    }
    redis_client.publish(channel, json.dumps(event))

@app.route('/api/events')
def sse_events():
    def event_stream():
        pubsub = redis_client.pubsub()
        pubsub.subscribe('build_events', 'approval_events', 'roadmap_events')
        for message in pubsub.listen():
            if message['type'] == 'message':
                yield f"data: {message['data'].decode('utf-8')}\n\n"
    return Response(event_stream(), mimetype='text/event-stream')

@app.route('/api/builds/<build_id>/status', methods=['GET'])
def get_build_status(build_id):
    return json.dumps({"build_id": build_id, "status": build_status.get(build_id, "unknown")})

@app.route('/api/builds/<build_id>/update', methods=['POST'])
def update_build_status(build_id):
    new_status = request.json.get('status')
    build_status[build_id] = new_status
    publish_event('build_events', 'build_status_updated', {
        'build_id': build_id,
        'status': new_status,
        'timestamp': datetime.now().isoformat()
    })
    return json.dumps({"status": "updated"})

@app.route('/api/status', methods=['GET'])
def get_status():
    return json.dumps(build_status)

if __name__ == '__main__':
    app.run(threaded=True)
